function showModal(title,text,actions){document.getElementById('modalTitle').textContent=title;document.getElementById('modalText').innerHTML=text;document.getElementById('modalActions').innerHTML=actions;document.getElementById('modal').classList.add('show')}
function closeModal(){document.getElementById('modal').classList.remove('show')}
function tick(){const now=Date.now(),dt=Math.min(3,Math.max(0,(now-(S._tick||now))/1000));S._tick=now;if(dt>0){for(const id in S.cooldowns)S.cooldowns[id]=Math.max(0,S.cooldowns[id]-dt);for(const id in S.buffs)S.buffs[id]=Math.max(0,S.buffs[id]-dt);damage(getDps()*dt,false);S.totalPlay+=dt;render()}save()}
function applyOffline(){const elapsed=Math.min(8*60*60,Math.max(0,(Date.now()-(S.last||Date.now()))/1000));if(elapsed<12)return;const kills=Math.floor(getDps()*elapsed/maxHp());if(kills<1)return;const count=Math.min(kills,10000),goldEach=goldReward();S.kills+=count;S.gold+=count*goldEach;S.goldEarned+=count*goldEach;addXp(count*(12+S.zone*2));const totalWaves=S.wave+count;S.zone+=Math.floor((totalWaves-1)/5);S.wave=((totalWaves-1)%5)+1;spawnEnemy();setTimeout(()=>toast(`While away: <strong>${fmt(count)} enemies</strong> defeated · +${fmt(count*goldEach)} gold`),250)}
document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>{activeView=b.dataset.view;document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.content-view').forEach(x=>x.classList.toggle('active',x.id===`view-${activeView}`));render()}));
document.addEventListener('click',e=>{const buy=e.target.closest('[data-buy]');if(buy)buyUpgrade(buy.dataset.buy);const skill=e.target.closest('[data-skill]');if(skill)useSkill(skill.dataset.skill);const claim=e.target.closest('[data-claim]');if(claim)claimQuest(claim.dataset.claim);const go=e.target.closest('[data-goto]');if(go){activeView=go.dataset.goto;document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.view===activeView));document.querySelectorAll('.content-view').forEach(x=>x.classList.toggle('active',x.id===`view-${activeView}`))}if(e.target.id==='ascendBtn')ascend()});
